Multi-tenancy security.ejemplo:
// Middleware que exige tenant_id firmado y lo propaga al contexto
func TenantMiddleware(next http.Handler) http.Handler {
  return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    tid := claimsFromJWT(r.Context()).TenantID
    if tid == "" { http.Error(w, "missing tenant", 403); return }
    next.ServeHTTP(w, r.WithContext(WithTenant(r.Context(), tid)))
  })
}

